"use strict";

const fs = require('fs');
const path = require('path');

const WORKSPACE = path.join(process.env.HOME, '.openclaw', 'workspace');
const LOG_FILE = path.join(WORKSPACE, 'BOT_MESSAGES.md');

// v2.4 修補（2026-06-09）：botId 不再寫死「1号機」，動態用 agentId
// 根因：三隻機共用 handler.js 全標「1号機」，造成 bot-relay-inbound 過濾失效，
// 三隻機物理上互相聽不到——「綜合討論群」3 個月前提崩塌。
const AGENT_NAME_MAP = { main: '🦞學長', kong: '🦐學弟', peipei: '🐰學妹' };

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sent') return;

  try {
    const ctx = event.context ?? {};
    const text = ctx.textContent ?? ctx.content ?? '';
    const msgId = ctx.messageId ?? ctx.id ?? 0;
    const chatId = ctx.chatId ?? '-1003877502911';
    const chatType = ctx.chatType ?? '';
    const agentId = ctx.agentId ?? 'unknown';

    // Skip empty or very short messages
    if (!text || text.trim().length < 2) return;

    // Only log messages in group chats (negative chatId)
    if (chatType === 'direct' || (typeof chatId === 'number' && chatId > 0)) return;

    const entry = {
      ts: new Date().toISOString(),
      botId: agentId,                                  // ← 改：動態 agentId（main/kong/peipei）
      botName: AGENT_NAME_MAP[agentId] || agentId,     // ← 新：人話名稱供 inbound 顯示
      text: text.substring(0, 200),
      msgId,
      chatId: String(chatId)
    };

    const line = JSON.stringify(entry) + '\n';

    fs.appendFileSync(LOG_FILE, line, 'utf8');
  } catch (err) {
    // Silent fail - don't disrupt message sending
  }
};

module.exports = handler;
module.exports.default = handler;

