const IDENTITY_LABELS = {
  main: '🦞 學長（1號機）',
  kong: '🦐 學弟（2號機）',
  peipei: '🦀 學妹（3號機）',
};

const WORKSPACE_DIR = path.join(os.homedir(), '.openclaw', 'workspace');
const SHARED_MEMORY_PATH = path.join(WORKSPACE_DIR, 'shared-context', 'SHARED_GROUP_MEMORY.md');

// ── Agent ID 偵測 ─────────────────────────────────────────
function getAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    '';
  return String(raw).toLowerCase();
}

// ── 群組 Session 偵測 ─────────────────────────────────────
// agent:bootstrap 的 context 只有 workspaceDir/bootstrapFiles/cfg/sessionKey/agentId
// 必須從 sessionKey 解析 peerKind（格式：agent:<id>:<channel>:<peerKind>:<peerId>）
function isLineGroupSession(event) {
  const sessionKey =
    (event && event.sessionKey) ||
    (event && event.context && event.context.sessionKey) ||
    '';
  return sessionKey.toLowerCase().includes('line:group');
}

function isGroupSession(event) {
  const sessionKey =
    (event && event.sessionKey) ||
    (event && event.context && event.context.sessionKey) ||
    '';

  if (sessionKey) {
    const parts = sessionKey.toLowerCase().split(':');
    // 格式：agent:<agentId>:<channel>:<peerKind>:<peerId>
    // 或：agent:<agentId>:<channel>:<accountId>:<peerKind>:<peerId>
    for (const part of parts) {
      if (part === 'group' || part === 'supergroup' || part === 'channel') return true;
    }
  }

  // fallback：舊版 context 欄位
  const ctx = (event && event.context) ? event.context : {};
  const chatType =
    (ctx.source && ctx.source.chat && ctx.source.chat.type) ||
    (ctx.session && ctx.session.chatType) ||
    ctx.chatType || '';
  if (['group', 'supergroup', 'channel'].includes(chatType)) return true;

  const chatId =
    (ctx.source && ctx.source.chat && ctx.source.chat.id) ||
    (ctx.session && ctx.session.chatId) ||
    ctx.chatId || 0;
  if (typeof chatId === 'number' && chatId < 0) return true;

  return false;
}

