"use strict";

const fs = require('fs');
const path = require('path');

const WORKSPACE = path.join(process.env.HOME, '.openclaw', 'workspace');
const LOG_FILE = path.join(WORKSPACE, 'BOT_MESSAGES.md');
const MAX_LINES = 30; // 最近 30 筆訊息（v2.4 拉大 buffer，提高跨機可見度）

// v2.4 修補（2026-06-09）：BOT_ID 不再寫死，動態依 event.context.agentId
// 修了 3 個月來的根因——三隻機物理上互相聽不到，「綜合討論」前提崩塌。
const AGENT_NAME_MAP = { main: '🦞學長', kong: '🦐學弟', peipei: '🐰學妹', '1号機': '🦞學長(舊)' };

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  try {
    if (!fs.existsSync(LOG_FILE)) return;

    const myAgentId = event.context.agentId ?? 'unknown';

    // 讀取最後 N 行
    const content = fs.readFileSync(LOG_FILE, 'utf-8');
    const lines = content.split('\n').filter(l => l.trim());
    const recent = lines.slice(-MAX_LINES);

    // 過濾掉自己發的訊息（動態 agentId）
    // 舊歷史資料全標「1号機」，學長(main)會誤排——但只是少看到自己歷史，影響小
    const others = recent.filter(line => {
      try {
        const entry = JSON.parse(line);
        return entry.botId !== myAgentId;
      } catch { return false; }
    });

    if (others.length === 0) return;

    // 格式化為可讀文字塊（用人話名稱）
    const blocks = others.map(line => {
      const entry = JSON.parse(line);
      const time = new Date(entry.ts).toLocaleTimeString('zh-TW', { hour: '2-digit', minute: '2-digit' });
      const name = entry.botName || AGENT_NAME_MAP[entry.botId] || entry.botId;
      return `[${time}] ${name}：${entry.text.substring(0, 120)}`;
    });

    const injection = [
      '---',
      '# 🦞 夥伴最近發言（其他機在分工群說的話，v2.4 真正聽得到）',
      '> 你（' + (AGENT_NAME_MAP[myAgentId] || myAgentId) + '）剛收到群裡訊息。以下是夥伴最近說的話，你必須先讀過再決定如何回應：',
      '',
      ...blocks.reverse().slice(0, 15).map(b => `• ${b}`),
      '',
      '> 💡 提醒：',
      '> - 如果議程說「先學弟」但你看到上面沒有 🦐學弟 的最新發言 → 你還要等',
      '> - 如果你已經看到所有該發言的夥伴都發完了 → 該輪到你或學長收尾了',
      '---',
    ].join('\n');

    if (!event.context.inject) event.context.inject = [];
    if (Array.isArray(event.context.inject)) {
      event.context.inject.unshift({ role: 'system', content: injection });
    }
  } catch (err) {
    // Silent fail
  }
};

module.exports = handler;
module.exports.default = handler;

