    if (agentId === MAIN_AGENT_ID) {
      // 學長：生議程注入
      const agenda = await generateAgenda(text);
      if (!agenda) return;
      injection = buildLeaderInjection(agenda);
    } else if (FOLLOWER_AGENT_IDS.includes(agentId)) {
      // 學弟學妹：注入硬性等待指令（不呼叫 LLM，省 token）
      injection = buildFollowerInjection(agentId);
    }

    if (!injection) return;
    if (!event.context.inject) event.context.inject = [];
    // OpenClaw 期望物件 { role, content }，用字串 push 會被忽略！
    // 用 unshift 注入到開頭，讓 LLM 優先看到（學 client-memory 的做法）
    event.context.inject.unshift({ role: 'system', content: injection });
  } catch (err) {
    // 靜默失敗，不影響訊息流轉
  }
};

module.exports = handler;

